-- Create T_LDAP_CONFIG table for multi-LDAP authentication support
create table T_LDAP_CONFIG ( LDC_ID_C varchar(36) not null, LDC_NAME_C varchar(100) not null, LDC_ORDER_N int not null, LDC_ENABLED_B bit not null, LDC_HOST_C varchar(250) not null, LDC_PORT_N int not null, LDC_USESSL_B bit not null, LDC_ADMIN_DN_C varchar(250) not null, LDC_ADMIN_PASSWORD_C varchar(250) not null, LDC_BASE_DN_C varchar(250) not null, LDC_FILTER_C varchar(250) not null, LDC_DEFAULT_EMAIL_C varchar(250) not null, LDC_DEFAULT_STORAGE_N bigint not null, LDC_DEFAULT_GROUP_C varchar(36), LDC_DEFAULT_GROUPMEMBERSHIP_C varchar(250), LDC_DELETEDATE_D datetime, primary key (LDC_ID_C) );

-- Migrate existing single LDAP configuration from T_CONFIG if present
insert into T_LDAP_CONFIG (LDC_ID_C, LDC_NAME_C, LDC_ORDER_N, LDC_ENABLED_B, LDC_HOST_C, LDC_PORT_N, LDC_USESSL_B, LDC_ADMIN_DN_C, LDC_ADMIN_PASSWORD_C, LDC_BASE_DN_C, LDC_FILTER_C, LDC_DEFAULT_EMAIL_C, LDC_DEFAULT_STORAGE_N, LDC_DEFAULT_GROUP_C, LDC_DEFAULT_GROUPMEMBERSHIP_C) select 'default-ldap-server', 'Primary LDAP', 0, case when exists (select 1 from T_CONFIG where CFG_ID_C = 'LDAP_ENABLED' and lower(CFG_VALUE_C) = 'true') then true else false end, coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_HOST'), 'localhost'), cast(coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_PORT'), '389') as int), case when exists (select 1 from T_CONFIG where CFG_ID_C = 'LDAP_USESSL' and lower(CFG_VALUE_C) = 'true') then true else false end, coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_ADMIN_DN'), ''), coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_ADMIN_PASSWORD'), ''), coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_BASE_DN'), ''), coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_FILTER'), '(uid=USERNAME)'), coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_DEFAULT_EMAIL'), 'devnull@localhost'), cast(coalesce((select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_DEFAULT_STORAGE'), '100000000') as bigint), (select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_DEFAULT_GROUP'), (select CFG_VALUE_C from T_CONFIG where CFG_ID_C = 'LDAP_DEFAULT_GROUPMEMBERSHIP') from T_CONFIG where CFG_ID_C = 'LDAP_HOST' and CFG_VALUE_C is not null and CFG_VALUE_C <> '';

-- Update DB version to 39
update T_CONFIG set CFG_VALUE_C = '39' where CFG_ID_C = 'DB_VERSION';
